add_action( 'admin_head', 'perfectpixel_admin_custom_css' );
add_action( 'login_head', 'perfectpixel_admin_custom_css_login' );

function perfectpixel_admin_custom_css() {
	// Nowdoc so quotes inside the CSS are kept as they are.
	$css = <<<'CSS'
{{admin_custom_css}}
CSS;
	$css = trim( wp_strip_all_tags( $css ) );
	if ( '' !== $css ) {
		echo '<style id="perfectpixel-admin-css">' . $css . '</style>' . "\n";
	}
}

function perfectpixel_admin_custom_css_login() {
	if ( 'yes' === strtolower( trim( '{{admin_custom_css_login}}' ) ) ) {
		perfectpixel_admin_custom_css();
	}
}
